'use strict';
const root=document.getElementById('app');
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=value=>Number(value||0).toLocaleString('en-US');
const id=()=>crypto.randomUUID();
let identity=null,view='dashboard',users=[],rechargeRequest=null,publicationRequest=null;
const pendingKey=()=>`sovera.control.pending-recharge.${identity.uid}`;
function savePending(){try{if(rechargeRequest)sessionStorage.setItem(pendingKey(),JSON.stringify(rechargeRequest));else sessionStorage.removeItem(pendingKey());}catch{}}
const $=name=>document.getElementById(name);
async function api(path,method='GET',body){
 const response=await fetch('/sovera/control/'+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),cache:'no-store'});
 const data=await response.json().catch(()=>({}));
 if(!response.ok){
  if(response.status===401){identity=null;login();}
  const error=Error(typeof data.detail==='string'?data.detail:'Request could not be completed.');error.status=response.status;throw error;
 }
 return data;
}
function login(message=''){
 root.innerHTML=`<main class="login"><div class="brand"><img class="brand-logo" src="/sovera-logo.png" alt="Sovera" width="72" height="72"><strong>Sovera Control</strong></div><h1>Your community workspace.</h1><p>Sign in with your assigned admin username and password.</p><form id="login"><label>Username<input id="username" autocomplete="username" minlength="3" maxlength="64" autocapitalize="none" spellcheck="false" required></label><label>Password<input id="password" type="password" autocomplete="current-password" maxlength="128" required></label><label>Authenticator / recovery code (if enabled)<input id="login-otp" autocomplete="one-time-code" maxlength="32"></label><button id="submit" class="full">Sign in</button><p id="error" role="alert" class="error">${esc(message)}</p></form><p class="help">Only assigned staff can sign in. Contact the owner if you need to reset your password.</p></main>`;
 $('login').onsubmit=async event=>{event.preventDefault();$('submit').disabled=true;try{await api('password-login','POST',{username:$('username').value.trim(),password:$('password').value,...($('login-otp').value.trim()?{otp:$('login-otp').value.trim()}:{})});await start();}catch(e){if($('error'))$('error').textContent=e.message;if($('submit'))$('submit').disabled=false;}};
}
const titles={dashboard:'Overview',operations:'Reports & audit',rooms:'Room moderation',security:'Security & sessions',programs:'VIP & referrals',payments:'Payment verification',agencyfinance:'Agency finance',schedules:'Scheduled notices',rewards:'Rewards & rankings',agencies:'Agencies',sellers:'Coin sellers',official:'Official messages',users:'Members',recharge:'Recharge coins',staff:'Staff access',publications:'Notices & events',support:'Support inbox',history:'Recharge history',banners:'Home banners',frames:'Profile frames',entries:'Entry animations',gifts:'Animated gifts',medals:'Medals',tags:'Profile tags',roomframes:'Room frames'};
function available(){
 const role=identity.role;
 return ['dashboard','security',...(role!=='support'?['users']:[]),...(role==='owner'||role==='agent'?['recharge','history']:[]),...(role==='owner'?['staff','sellers','agencies','rewards','operations','programs','payments','agencyfinance']:[]),...(role==='owner'||role==='admin'?['rooms','schedules','banners','frames','entries','gifts','medals','tags','roomframes','publications','official']:[]),...(role!=='agent'?['support']:[])];
}
function shell(){
 root.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img class="brand-logo" src="/sovera-logo.png" alt="Sovera" width="52" height="52"><strong>Sovera Control</strong><button id="menu-close" class="secondary mobile-menu" aria-label="Close navigation">×</button></div><nav class="nav" aria-label="Admin sections">${available().map(name=>`<button data-view="${name}" class="${view===name?'active':''}">${titles[name]}</button>`).join('')}</nav><div class="foot"><p>${esc(identity.name)} · ${esc(identity.role)}</p></div></aside><main class="main"><header class="topbar"><button id="menu-toggle" class="secondary mobile-menu" aria-label="Open navigation" aria-expanded="false">☰ Menu</button><div><small class="eyebrow">SOVERA / CONTROL</small><h1>${titles[view]}</h1></div><button id="logout" class="secondary">Sign out</button></header><p id="error" role="alert" class="error"></p><div id="panel">Loading…</div></main></div>`;
 root.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>{view=button.dataset.view;render();});
 $('menu-close').onclick=()=>root.querySelector('.shell').classList.remove('menu-open');
 $('menu-toggle').onclick=()=>{const opened=root.querySelector('.shell').classList.toggle('menu-open');$('menu-toggle').setAttribute('aria-expanded',String(opened));};
 $('logout').onclick=async()=>{try{await api('logout','POST',{});identity=null;login();}catch(e){$('error').textContent=e.message;}};
}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table>${rows.length?'':'<p class="empty">No records yet.</p>'}</div>`;}
async function render(){
 shell();
 try{if(assetKinds[view])await assets();else await ({dashboard,members,recharge,staff,publications,support,history,sellers,agencies,rewards,operations,rooms:moderationRooms,security,programs,payments,agencyfinance,schedules,official:officialMessages}[view==='users'?'members':view])();}
 catch(e){if($('error'))$('error').textContent=e.message;if($('panel')&&$('panel').textContent==='Loading…')$('panel').textContent='This section could not be loaded. Choose it again to retry.';}
}
function dashboard(){
 $('panel').innerHTML=`<div class="metrics">${[['Members',identity.users],['Saved rooms',identity.rooms],['Unanswered support',identity.open_tickets]].map(([name,value])=>`<section class="card metric"><small>${name}</small><div class="value">${num(value)}</div></section>`).join('')}</div><section class="card"><h2>Welcome, ${esc(identity.name)}</h2><p>Assigned role: ${esc(identity.role)}</p>${identity.quota_remaining===null?'':`<p>Recharge quota remaining: <b>${num(identity.quota_remaining)} Coins</b></p>`}<p class="help">Balances and records come from your Sovera server. Existing wallets must be reconciled before recharges or game spending can be enabled.</p></section>`;
}
async function members(){
 users=(await api('users')).items;
 $('panel').innerHTML='<section class="card"><label>Find by account ID, name or verified legacy reference<input id="search" type="search"></label><div id="results"></div><button id="more-members" class="secondary">Load more members</button></section>';
 const draw=()=>{
  const q=$('search').value.trim().toLowerCase();
  const rows=users.filter(u=>[u.uid,u.public_id,u.name,u.source_ref,u.country].some(v=>String(v??'').toLowerCase().includes(q)));
  $('results').innerHTML=table(['Member','Account ID','Country','Status / room','Role','Coins','Diamonds','Wallet','Details'],rows.map(u=>`<tr><td>${esc(u.name)}</td><td class="details">${u.public_id?'ID '+esc(u.public_id)+'<br>':''}${esc(u.uid)}</td><td>${esc(u.country)}</td><td>${u.last_seen>Date.now()/1000-90?'Online':'Offline'}<br>${esc(u.current_room||'—')}</td><td>${esc(u.role||'Member')}</td><td>${u.wallet_status?num(u.coins):'Not verified'}</td><td>${u.wallet_status?num(u.diamonds):'—'}</td><td>${esc(u.wallet_status||'Awaiting migration')}</td><td><button data-user-details="${esc(u.uid)}">View / assign assets</button></td></tr>`));
  root.querySelectorAll('[data-user-details]').forEach(b=>b.onclick=()=>userDetails(b.dataset.userDetails).catch(e=>{$('error').textContent=e.message;}));
 };
 let searchTimer;
 $('search').oninput=()=>{clearTimeout(searchTimer);const query=$('search').value.trim();searchTimer=setTimeout(async()=>{try{const data=await api('users?q='+encodeURIComponent(query));if(!$('search')||$('search').value.trim()!==query)return;users=data.items;draw();}catch(e){if($('error'))$('error').textContent=e.message;}},250);};
 $('more-members').onclick=async()=>{const query=$('search').value.trim();$('more-members').disabled=true;try{const data=await api('users?q='+encodeURIComponent(query)+'&offset='+users.length);if(!$('search')||$('search').value.trim()!==query)return;users.push(...data.items);draw();$('more-members').hidden=data.items.length<200;}catch(e){if($('error'))$('error').textContent=e.message;}finally{if($('more-members'))$('more-members').disabled=false;}};
 $('more-members').hidden=users.length<200;draw();
}
async function recharge(){
 users=(await api('users')).items;
 $('panel').innerHTML=`<section class="card"><h2>Recharge by account</h2><p>Select a member and verify their name and wallet before issuing coins.</p><label>Search public ID or member name<input id="recharge-search" type="search"></label><form id="recharge"><label>Member<select id="target" required><option value="">Choose member</option>${users.map(u=>`<option value="${esc(u.uid)}">${esc(u.name)} · ${esc(u.public_id||u.source_ref||u.uid)}</option>`).join('')}</select></label><div id="target-info"></div><label>Coins<input id="amount" type="number" min="1" max="9007199254740991" step="1" required></label><p>10K = 10,000 · 100K = 100,000 · 1M = 1,000,000 · 2M = 2,000,000</p><label>Note<input id="note" maxlength="300"></label><button id="submit">Review recharge</button></form><div id="receipt" aria-live="polite"></div></section>`;
 $('target').onchange=()=>{
  const user=users.find(u=>u.uid===$('target').value);
  $('target-info').textContent=user?`${user.name} · ${user.wallet_status==='active'?num(user.coins)+' Coins':'Wallet not active or not migrated'}`:'';
 };
 let lookupTimer;
 $('recharge-search').oninput=()=>{clearTimeout(lookupTimer);const query=$('recharge-search').value.trim();lookupTimer=setTimeout(async()=>{try{const data=await api('users?q='+encodeURIComponent(query));if(!$('recharge-search')||$('recharge-search').value.trim()!==query)return;users=data.items;$('target').innerHTML='<option value="">Choose member</option>'+users.map(u=>`<option value="${esc(u.uid)}">${esc(u.name)} · ${esc(u.public_id||u.uid)}</option>`).join('');$('target').onchange();}catch(e){$('error').textContent=e.message;}},250);};
 if(rechargeRequest){$('recharge-search').disabled=true;$('target').value=rechargeRequest.target_uid;$('amount').value=rechargeRequest.amount;$('note').value=rechargeRequest.note;for(const field of ['target','amount','note'])$(field).disabled=true;$('submit').textContent='Retry same recharge';$('target').onchange();}
 $('recharge').onsubmit=async event=>{
  event.preventDefault();
  const target=users.find(u=>u.uid===$('target').value);
  if(!target||target.wallet_status!=='active'){$('error').textContent='This wallet must be verified and active first.';return;}
  const amount=Number($('amount').value);
  if(!Number.isSafeInteger(amount)||amount<1)return;
  if(!rechargeRequest&&!confirm(`Recharge ${num(amount)} Coins to ${target.name} (${target.uid})?`))return;
  rechargeRequest??={target_uid:target.uid,amount,note:$('note').value,request_id:id()};savePending();
  $('submit').disabled=true;
  for(const field of ['target','amount','note'])$(field).disabled=true;
  try{const result=await api('recharge','POST',rechargeRequest);rechargeRequest=null;savePending();if(!$('receipt'))return;$('receipt').innerHTML=`<div class="receipt"><strong>Recharge successful</strong><p>${esc(target.name)} received ${num(result.amount)} Coins.</p><p>Balance after this recharge: ${num(result.balance)} Coins</p><p class="details">Receipt: ${esc(result.request_id)}</p><button id="another">New recharge</button></div>`;$('another').onclick=recharge;}
  catch(e){$('error').textContent=e.message;$('submit').disabled=false;$('submit').textContent='Retry same recharge';}
 };
}
async function staff(){
 const exchangePolicy=await api('exchange-policy');
 const rows=(await api('staff')).items;
 const credentials=(await api('staff/credentials')).items;
 const people=(await api('users')).items;
 $('panel').innerHTML=`<section class="card"><h2>Assigned staff</h2>${table(['Account','Role','Quota','Issued'],rows.map(r=>`<tr><td class="details">${esc(r.uid)}</td><td>${esc(r.role)}</td><td>${r.quota===null?'—':num(r.quota)}</td><td>${r.used===null?'—':num(r.used)}</td></tr>`))}</section><section class="card space"><h2>Assign permissions</h2><form id="staff"><label>Member<select id="target" required>${people.filter(u=>u.uid!==identity.uid).map(u=>`<option value="${esc(u.uid)}">${esc(u.name)} · ${esc(u.uid)}</option>`).join('')}</select></label><label>Role<select id="role"><option value="support">Support replies only</option><option value="admin">Support and publications</option><option value="agent">Recharge within quota</option><option value="none">Revoke access</option></select></label><label>Total recharge quota<input id="quota" type="number" min="0" max="9007199254740991" value="0" required></label><p class="help">Quota is the lifetime total permitted for this agent; previously issued coins remain counted. Owner access can only be provisioned on the server console.</p><button id="submit">Save staff access</button></form></section>`;
 const revokePanel=document.createElement('section');revokePanel.className='card space';revokePanel.innerHTML='<h2>Remove staff access</h2><p>Ends active sessions and removes this staff login. Restoring a role later requires a new login assignment.</p>'+rows.filter(r=>r.role!=='owner').map(r=>'<p>'+esc(r.uid)+' · '+esc(r.role)+' <button data-revoke-staff="'+esc(r.uid)+'">Remove access</button></p>').join('');$('panel').append(revokePanel);
 revokePanel.querySelectorAll('[data-revoke-staff]').forEach(b=>b.onclick=async()=>{if(!confirm('Remove all admin access for '+b.dataset.revokeStaff+' and sign them out?'))return;b.disabled=true;try{await api('staff','POST',{target_uid:b.dataset.revokeStaff,role:'none',quota:0});await staff();}catch(e){$('error').textContent=e.message;b.disabled=false;}});
 const exchangePanel=document.createElement('section');exchangePanel.className='card space';exchangePanel.innerHTML=`<h2>Diamond exchange rate</h2><form id="exchange-policy"><label>Coins received per 100 Diamonds (1–100)<input id="exchange-rate" type="number" min="1" max="100" value="${exchangePolicy.coins_per_100}" required></label><p>40 means 100 Diamonds → 40 Coins. Completed exchanges keep their original rate.</p><button>Save exchange rate</button></form>`;$('panel').append(exchangePanel);
 $('exchange-policy').onsubmit=async e=>{e.preventDefault();try{await api('exchange-policy','PUT',{coins_per_100:Number($('exchange-rate').value)});$('error').textContent='Exchange rate saved for future exchanges.';}catch(err){$('error').textContent=err.message;}};
 const credentialPanel=document.createElement('section');credentialPanel.className='card space';
 credentialPanel.innerHTML='<h2>Staff username & password</h2><p>First assign a role above, then create a login here. Setting a new password signs this staff member out of existing sessions. Existing Authenticator protection stays enabled. Owner login is managed separately.</p><form id="staff-password"><label>Assigned staff<select id="credential-target" required>'+credentials.map(r=>'<option value="'+esc(r.uid)+'">'+esc(r.uid)+' · '+esc(r.role)+' · '+esc(r.username||'No username yet')+'</option>').join('')+'</select></label><label>Username<input id="credential-username" autocomplete="off" autocapitalize="none" minlength="3" maxlength="64" pattern="[a-zA-Z0-9_.-]{3,64}" required></label><label>New password<input id="credential-password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required></label><button id="credential-save" '+(credentials.length?'':'disabled')+'>Create / reset staff login</button></form><p id="credential-result" role="status"></p>';
 $('panel').append(credentialPanel);
 const fillCredential=()=>{$('credential-username').value=credentials.find(r=>r.uid===$('credential-target').value)?.username||'';$('credential-password').value='';};
 $('credential-target').onchange=fillCredential;fillCredential();
 $('staff-password').onsubmit=async event=>{
   event.preventDefault();const target=$('credential-target').value;
   if(!confirm('Create or reset login for '+target+'? Existing sessions for this staff account will be signed out.'))return;
   $('credential-save').disabled=true;
   try{
     await api('staff/credentials','POST',{target_uid:target,username:$('credential-username').value.trim(),password:$('credential-password').value});
     $('credential-password').value='';$('credential-result').textContent='Staff login saved. Share the admin panel link and credentials privately with this staff member. Previous sessions were signed out.';
   }catch(error){$('credential-password').value='';$('error').textContent=error.message;}
   finally{if($('credential-save'))$('credential-save').disabled=false;}
 };
 $('staff').onsubmit=async event=>{event.preventDefault();$('submit').disabled=true;try{await api('staff','POST',{target_uid:$('target').value,role:$('role').value,quota:Number($('quota').value)});await staff();}catch(e){$('error').textContent=e.message;$('submit').disabled=false;}};
}
function publications(){
 $('panel').innerHTML='<section class="card"><h2>Publish to the app</h2><form id="publication"><label>Section<select id="section"><option value="notices">Official notice</option><option value="events">Community event</option></select></label><label>Title<input id="title" maxlength="100" required></label><label>Details<textarea id="text" maxlength="1000" required></textarea></label><p class="help">Event announcements appear in the app. Automated prizes are a separate service.</p><button id="submit">Publish</button></form><p id="receipt" aria-live="polite"></p></section>';
 if(publicationRequest){for(const field of ['section','title','text']){$(field).value=publicationRequest[field];$(field).disabled=true;}$('submit').textContent='Retry same publication';}
 $('publication').onsubmit=async event=>{event.preventDefault();publicationRequest??={section:$('section').value,title:$('title').value,text:$('text').value,request_id:id()};$('submit').disabled=true;for(const field of ['section','title','text'])$(field).disabled=true;try{await api('publications','POST',publicationRequest);publicationRequest=null;publications();$('receipt').textContent='Published successfully.';}catch(e){$('error').textContent=e.message;$('submit').disabled=false;$('submit').textContent='Retry publication';}};
}
async function support(){
 const rows=(await api('operations/tickets')).items;
 $('panel').innerHTML=`<section class="card"><h2>Support requests</h2>${rows.length?'':'<p>No requests yet.</p>'}${rows.map(t=>`<article class="ticket"><h3>${esc(t.name)}</h3><p>${esc(t.text)}</p><form data-route-ticket="${t.id}"><label>Status<select name="state">${['open','in_progress','resolved'].map(v=>`<option ${t.status===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Assigned staff UID<input name="assignee" value="${esc(t.assignee)}" maxlength="128"></label><label>Internal note<textarea name="note" maxlength="500">${esc(t.note)}</textarea></label><button>Save routing</button></form><form data-ticket="${t.id}"><label>Your reply<textarea maxlength="1000" required>${esc(t.reply)}</textarea></label><button>Send reply</button></form></article>`).join('')}</section>`;
 root.querySelectorAll('[data-route-ticket]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{await api('operations/tickets/'+f.dataset.routeTicket,'PUT',{status:f.elements.state.value,assignee:f.elements.assignee.value,note:f.elements.note.value});await support();}catch(err){$('error').textContent=err.message;}});
 root.querySelectorAll('[data-ticket]').forEach(form=>form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('button');button.disabled=true;try{await api('support/'+form.dataset.ticket,'PUT',{text:form.querySelector('textarea').value,request_id:id()});button.textContent='Reply saved';}catch(e){$('error').textContent=e.message;}finally{button.disabled=false;}});
}
async function history(){
 const rows=(await api('history')).items;
 $('panel').innerHTML=`<section class="card">${table(['Receipt','Account','Coins','Balance after','Note'],rows.map(r=>`<tr><td class="details">${esc(r.request_id)}</td><td class="details">${esc(r.target)}</td><td>${num(r.amount)}</td><td>${num(r.balance)}</td><td>${esc(r.note)}</td></tr>`))}</section>`;
}
async function start(){try{identity=await api('session');try{rechargeRequest=JSON.parse(sessionStorage.getItem(pendingKey())||'null');}catch{rechargeRequest=null;}if(!available().includes(view))view='dashboard';await render();}catch(e){login(e.message==='Sign in required'?'':e.message);}}
const assetKinds={banners:'banner',frames:'frame',entries:'entry',gifts:'gift',medals:'medal',tags:'tag',roomframes:'room_frame'};
let catalogRows=[],editingAsset=null,uploadedMedia=null;
const mediaPreview=key=>'/sovera/control/media/'+encodeURIComponent(key);
async function assets(){
 const kind=assetKinds[view];catalogRows=(await api('catalog')).items;editingAsset=null;uploadedMedia=null;
 const rows=catalogRows.filter(r=>r.kind===kind);
 $('panel').innerHTML=`<section class="card"><h2>${esc(titles[view])}</h2><p>Upload PNG, JPG, animated GIF or WebP from your gallery. Maximum 8 MB, 4096 px and 300 animation frames. Use a transparent image for frames.</p><button id="new-asset">Add new</button><div class="content-grid space">${rows.map(r=>`<article class="content-item">${r.builtin_slide!==undefined?`<div style="display:flex;align-items:center;gap:12px;padding:18px;border-radius:20px;background:linear-gradient(130deg,#26233f,#171b30);min-height:160px"><div><small>SOVERA COMMUNITY</small><h3>${esc(r.title)}</h3><p>${esc(r.subtitle||'')}</p></div><img style="width:62px;height:62px;object-fit:contain" src="${mediaPreview(r.media_id)}" alt="Sovera"></div>`:`<img src="${mediaPreview(r.media_id)}" alt="${esc(r.title)}">`}<h3>${esc(r.title)}</h3><p>${r.builtin_slide!==undefined?esc(r.subtitle||'Original home banner')+' · ':''}${num(r.price)} Coins · ${r.active?'Active':'Hidden'} · Order ${r.position}</p><button data-edit="${esc(r.id)}">Edit / preview</button>${identity.role==='owner'&&!['banner','gift'].includes(kind)?`<button data-assign="${esc(r.id)}">Give to user</button>`:''}<button class="secondary" data-toggle="${esc(r.id)}">${r.active?'Hide':'Publish'}</button></article>`).join('')}</div><p>${rows.length?'':'No items in this category yet.'}</p></section><div id="asset-editor"></div>`;
 $('new-asset').onclick=()=>assetEditor(kind);
 root.querySelectorAll('[data-assign]').forEach(b=>b.onclick=()=>assetGrantChooser(catalogRows.find(r=>r.id===b.dataset.assign)));
 root.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>assetEditor(kind,catalogRows.find(r=>r.id===b.dataset.edit)));
 root.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const row=catalogRows.find(r=>r.id===b.dataset.toggle);await api('catalog','POST',itemPayload(row,{active:!row.active}));await assets();}catch(e){$('error').textContent=e.message;b.disabled=false;}});
}
function assetGrantChooser(item){
 $('asset-editor').innerHTML=`<section class="card"><h2>Give ${esc(item.title)} to a user</h2><p>Owner grant: no Coins are deducted. This does not grant a staff role.</p><form id="grant-search"><label>User ID, name or Firebase ID<input id="grant-query" required maxlength="128"></label><button>Find user</button></form><div id="grant-results"></div><p id="grant-message" role="status"></p></section>`;
 $('grant-search').onsubmit=async event=>{
  event.preventDefault();
  try{
   const people=(await api('users?q='+encodeURIComponent($('grant-query').value.trim()))).items;
   $('grant-results').innerHTML=people.length?`<form id="quick-grant"><label>User<select id="quick-user">${people.map(p=>`<option value="${esc(p.uid)}">${esc(p.name)} · ${esc(p.public_id||p.uid)}</option>`).join('')}</select></label><label>Duration in days (0 = permanent)<input id="quick-days" type="number" min="0" max="3650" value="0" required></label><label class="check"><input id="quick-equip" type="checkbox" checked>Equip immediately</label><button id="quick-submit">Confirm free owner grant</button></form>`:'<p>No matching user.</p>';
   if(!people.length)return;
   $('quick-grant').onsubmit=async event=>{
    event.preventDefault();$('quick-submit').disabled=true;
    try{await api('catalog/grant','POST',{target_uid:$('quick-user').value,item_id:item.id,equip:$('quick-equip').checked,revoke:false,days:Number($('quick-days').value)});$('grant-message').textContent='Assigned successfully. The user can refresh their profile.';}
    catch(e){$('grant-message').textContent=e.message;}
    finally{$('quick-submit').disabled=false;}
   };
  }catch(e){$('grant-message').textContent=e.message;}
 };
 $('asset-editor').scrollIntoView({behavior:'smooth',block:'start'});
}

function itemPayload(row,changes={}){const {id,kind,title,media_id,price,active,position,avatar_scale,avatar_x,avatar_y}=row;return {id,kind,title,media_id,price,active,position,avatar_scale,avatar_x,avatar_y,...changes};}
function assetEditor(kind,row){
 editingAsset=row??{id:id(),kind,title:'',media_id:'',price:0,active:true,position:0,avatar_scale:.46,avatar_x:.5,avatar_y:.5};uploadedMedia=null;
 $('asset-editor').innerHTML=`<section class="card"><h2>${row?'Edit':'New'} ${esc(kind.replaceAll('_',' '))}</h2><form id="asset-form"><label>Name<input id="asset-title" maxlength="80" value="${esc(editingAsset.title)}" required></label><label>Gallery image / animation<input id="asset-file" type="file" accept="image/png,image/jpeg,image/gif,image/webp"></label><div class="asset-preview fit-preview"><div id="fit-avatar" class="fit-avatar">USER</div><img id="fit-image" alt="Asset preview" ${editingAsset.media_id?`src="${mediaPreview(editingAsset.media_id)}"`:''}></div><p id="upload-info" class="help" aria-live="polite">${editingAsset.media_id?'Saved image loaded.':'Choose an image.'}</p><div class="cols"><label>Price in Coins (paid items require purchase or owner grant)<input id="asset-price" type="number" min="0" max="1000000000" value="${editingAsset.price}" required></label><label>Display order<input id="asset-order" type="number" min="0" max="10000" value="${editingAsset.position}" required></label></div>${kind==='gift'?'<p class="help">For paid gifts: each recipient receives Diamonds equal to the per-recipient Coin price. All wallets must be verified. Free gifts do not award Diamonds.</p>':''}<fieldset ${['frame','entry','room_frame'].includes(kind)?'':'hidden'}><legend>Avatar fit</legend><label>Avatar size<input id="fit-scale" type="range" min=".25" max=".8" step=".01" value="${editingAsset.avatar_scale}"></label><label>Horizontal center<input id="fit-x" type="range" min=".2" max=".8" step=".01" value="${editingAsset.avatar_x}"></label><label>Vertical center<input id="fit-y" type="range" min=".2" max=".8" step=".01" value="${editingAsset.avatar_y}"></label></fieldset><label class="check"><input id="asset-active" type="checkbox" ${editingAsset.active?'checked':''}>Show in app</label><button id="save-asset" class="space">Save and publish to app</button><p id="asset-message" role="status"></p></form></section>`;
 const fit=()=>{const avatar=$('fit-avatar'),scale=Number($('fit-scale').value),radius=scale/2;const center=value=>Math.max(radius,Math.min(1-radius,Number(value)));$('fit-x').value=center($('fit-x').value);$('fit-y').value=center($('fit-y').value);avatar.style.width=avatar.style.height=scale*100+'%';avatar.style.left=Number($('fit-x').value)*100+'%';avatar.style.top=Number($('fit-y').value)*100+'%';avatar.hidden=!['frame','entry','room_frame'].includes(kind);};
 for(const field of ['fit-scale','fit-x','fit-y'])$(field).oninput=fit;fit();
 $('asset-file').onchange=async()=>{
  const file=$('asset-file').files?.[0];if(!file)return;
  if(file.size>8*1024*1024){$('upload-info').textContent='Choose an image smaller than 8 MB.';return;}
  $('save-asset').disabled=true;$('upload-info').textContent='Uploading image…';uploadedMedia=null;
  try{
   const result=await fetch('/sovera/control/media',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/octet-stream'},body:file});
   const data=await result.json();if(!result.ok)throw Error(typeof data.detail==='string'?data.detail:'Upload failed');
   uploadedMedia=data.id;$('fit-image').src=mediaPreview(data.id);$('upload-info').textContent=`Uploaded ${data.width} × ${data.height} · ${data.frames} frame(s). Review fit, then save.`;
  }catch(e){$('upload-info').textContent=e.message;}finally{$('save-asset').disabled=false;}
 };
 $('asset-form').onsubmit=async event=>{
  event.preventDefault();const media=uploadedMedia||editingAsset.media_id;if(!media){$('asset-message').textContent='Upload an image first.';return;}
  $('save-asset').disabled=true;
  try{await api('catalog','POST',itemPayload(editingAsset,{title:$('asset-title').value,media_id:media,price:Number($('asset-price').value),position:Number($('asset-order').value),active:$('asset-active').checked,avatar_scale:Number($('fit-scale').value),avatar_x:Number($('fit-x').value),avatar_y:Number($('fit-y').value)}));await assets();$('error').textContent='Saved. The app loads published changes on refresh.';}
  catch(e){$('asset-message').textContent=e.message;$('save-asset').disabled=false;}
 };
 $('asset-editor').scrollIntoView({behavior:'smooth',block:'start'});
}
async function userDetails(uid){
 const data=await api('users/'+encodeURIComponent(uid)),p=data.profile;
 $('panel').innerHTML=`<section class="card"><button id="back-members" class="secondary">← Members</button><h2 class="space">${esc(p.display_name)}</h2><p class="details">Firebase ID: ${esc(p.firebase_uid)}</p><p>Country: ${esc(p.country)} · ${data.online?'Online':'Offline'}</p><p>Current room: ${esc(data.online?data.presence?.room_name||'—':'—')}</p><p>Gift Coins sent · Last 24h: ${num(data.sending?.daily||0)} · Last 7 days: ${num(data.sending?.weekly||0)} · Last 30 days: ${num(data.sending?.monthly||0)}</p><p>Bio: ${esc(p.bio||'—')}</p><p>Profile updated: ${new Date(p.updated_at*1000).toLocaleString()}</p><p>Wallet: ${esc(data.wallet?.status||'Awaiting verification')} · Legacy reference: ${esc(data.wallet?.source_ref||'—')}</p><p>Owned rooms: ${data.rooms.map(r=>esc(r.name)).join(', ')||'—'}</p><h3>Equipped assets</h3>${Object.entries(data.equipped).map(([k,r])=>`<span class="badge">${esc(k)}: ${esc(r.title)}</span>`).join(' ')||'<p>No assets equipped.</p>'}<div id="member-control"></div><div id="grant-editor"></div></section>`;
 $('back-members').onclick=members;
 await memberControl(uid,data);
 if(identity.role==='owner'){
  const wear=(await api('catalog')).items.filter(r=>!['banner','gift'].includes(r.kind));
  $('grant-editor').innerHTML=`<h3 class="space">Assign frames, entries, medals and tags</h3><form id="asset-grant"><label>Asset<select id="grant-item" required>${wear.map(r=>`<option value="${esc(r.id)}">${esc(r.kind)} · ${esc(r.title)}${data.owned.includes(r.id)?' (owned)':''}</option>`).join('')}</select></label><label>Duration in days (0 = permanent)<input id="grant-days" type="number" min="0" max="3650" value="0" required></label><label class="check"><input id="grant-equip" type="checkbox" checked>Equip immediately</label><label class="check"><input id="grant-revoke" type="checkbox">Revoke this asset</label><button id="grant-submit" class="space" ${wear.length?'':'disabled'}>Save assignment</button></form>`;
  $('asset-grant').onsubmit=async event=>{event.preventDefault();$('grant-submit').disabled=true;try{await api('catalog/grant','POST',{target_uid:uid,item_id:$('grant-item').value,equip:$('grant-equip').checked,revoke:$('grant-revoke').checked,days:Number($('grant-days').value)});await userDetails(uid);}catch(e){$('error').textContent=e.message;$('grant-submit').disabled=false;}};
 }
}

start();

async function sellers(){
 const rows=(await api('sellers')).items;
 const pack=await api('sellers/package'),assets=(await api('catalog')).items;
 $('panel').innerHTML=`<section class="card"><h2>Approved coin sellers</h2><form id="seller-package"><h3>Automatic seller welcome package</h3><p>New approvals receive and equip these assets. Existing owned assets are preserved when a listing is removed.</p>${['frame','tag','medal'].map(kind=>`<label>${esc(kind)}<select id="seller-package-${kind}"><option value="">No asset</option>${assets.filter(a=>a.kind===kind&&a.active).map(a=>`<option value="${esc(a.id)}" ${pack[kind]===a.id?'selected':''}>${esc(a.title)}</option>`).join('')}</select></label>`).join('')}<button>Save package</button></form><p>Listings expose the seller's profile and current Coin balance to members. Seller status alone does not grant admin or recharge access.</p>${table(['Seller','ID','Coins','Action'],rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.public_id||r.uid)}</td><td>${num(r.coins)}</td><td><button data-remove-seller="${esc(r.uid)}">Remove listing</button></td></tr>`))}<form id="seller-search"><label>Find member by name or ID<input id="seller-query" required maxlength="128"></label><button>Search</button></form><div id="seller-results"></div></section>`;
 $('seller-package').onsubmit=async event=>{event.preventDefault();try{await api('sellers/package','POST',Object.fromEntries(['frame','tag','medal'].map(k=>[k,$('seller-package-'+k).value])));$('error').textContent='Seller package saved.';}catch(e){$('error').textContent=e.message;}};
 root.querySelectorAll('[data-remove-seller]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('sellers','POST',{target_uid:b.dataset.removeSeller,enabled:false});await sellers();}catch(e){$('error').textContent=e.message;b.disabled=false;}});
 $('seller-search').onsubmit=async event=>{event.preventDefault();try{const people=(await api('users?q='+encodeURIComponent($('seller-query').value.trim()))).items;$('seller-results').innerHTML=people.map(r=>`<p>${esc(r.name)} · ${esc(r.public_id||r.uid)} <button data-add-seller="${esc(r.uid)}">Approve seller</button></p>`).join('')||'No matching member.';root.querySelectorAll('[data-add-seller]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('sellers','POST',{target_uid:b.dataset.addSeller,enabled:true});await sellers();}catch(e){$('error').textContent=e.message;b.disabled=false;}});}catch(e){$('error').textContent=e.message;}};
}
let noticeRequest=null;
function officialMessages(){
 $('panel').innerHTML='<section class="card"><h2>Private official message</h2><p>Use Notices & events for updates to everyone. This message is delivered only to the selected member.</p><form id="notice-search"><label>Find member by name or ID<input id="notice-query" required maxlength="128"></label><button>Search</button></form><div id="notice-members"></div><form id="official-form"><label>Title<input id="notice-title" maxlength="100" required></label><label>Message<textarea id="notice-text" maxlength="1000" required></textarea></label><button id="notice-submit">Send official message</button></form><p id="notice-receipt" role="status"></p></section>';
 $('notice-search').onsubmit=async event=>{event.preventDefault();try{const rows=(await api('users?q='+encodeURIComponent($('notice-query').value.trim()))).items;$('notice-members').innerHTML=`<label>Recipient<select id="notice-target">${rows.map(r=>`<option value="${esc(r.uid)}">${esc(r.name)} · ${esc(r.public_id||r.uid)}</option>`).join('')}</select></label>`;}catch(e){$('error').textContent=e.message;}};
 if(noticeRequest){$('notice-title').value=noticeRequest.title;$('notice-text').value=noticeRequest.text;for(const key of ['notice-title','notice-text','notice-query'])$(key).disabled=true;$('notice-submit').textContent='Retry same message';}
 $('official-form').onsubmit=async event=>{event.preventDefault();if(!noticeRequest&&!$('notice-target')?.value){$('error').textContent='Find and select a recipient first.';return;}noticeRequest??={target_uid:$('notice-target').value,title:$('notice-title').value,text:$('notice-text').value,request_id:id()};$('notice-submit').disabled=true;try{await api('official-messages','POST',noticeRequest);noticeRequest=null;officialMessages();$('notice-receipt').textContent='Official message delivered.';}catch(e){$('error').textContent=e.message;officialMessages();$('error').textContent=e.message;}};
}

async function memberControl(uid,data){
 const p=data.profile;
 $('member-control').innerHTML=`<h3>Account ID ${esc(p.public_id||'—')}</h3><p>Followers: ${num(data.social?.followers)} · Following: ${num(data.social?.following)} · Visitors: ${num(data.social?.visitors)}</p><p>Coins: ${num(data.coins)} · Diamonds: ${num(data.diamonds)} · ${data.banned?'Banned: '+esc(data.banned.reason):'Active'}</p><button id="member-history">Wallet & gift history</button><div id="member-history-panel"></div>${identity.role==='owner'?`<form id="member-profile"><h3>Edit profile</h3><label>Name<input id="member-name" value="${esc(p.display_name)}" maxlength="40" required></label><label>Country code<input id="member-country" value="${esc(p.country)}" maxlength="2" required></label><label>Gender<select id="member-gender"><option value="">Not set</option>${["male","female","other"].map(g=>`<option ${p.gender===g?"selected":""}>${g}</option>`).join("")}</select></label><label>Birthday<input id="member-birthday" type="date" value="${esc(p.birthday||'')}"></label><label class="check"><input id="member-remove-avatar" type="checkbox">Remove profile photo</label><label>Bio<textarea id="member-bio" maxlength="150">${esc(p.bio)}</textarea></label><button>Save profile</button></form><form id="member-adjust"><h3>Add / remove Coins</h3><label>Coin change (negative removes Coins)<input id="adjust-amount" type="number" min="-1000000000" max="1000000000" step="1" required></label><label>Reason<input id="adjust-note" minlength="3" maxlength="300" required></label><button id="adjust-submit">Review adjustment</button></form>${uid!==identity.uid?`<form id="member-ban"><label>Reason<input id="ban-reason" maxlength="300" value="${esc(data.banned?.reason||'')}"></label><button id="ban-submit">${data.banned?'Unban account':'Ban account'}</button></form>`:''}`:''}<p id="member-receipt" role="status"></p>`;
 $('member-history').onclick=()=>memberHistory(uid).catch(e=>{$('error').textContent=e.message;});
 if(identity.role!=='owner')return;
 $('member-profile').onsubmit=async event=>{event.preventDefault();try{await api('users/'+encodeURIComponent(uid)+'/profile','PUT',{display_name:$('member-name').value,country:$('member-country').value.toUpperCase(),bio:$('member-bio').value,avatar_url:$('member-remove-avatar').checked?null:p.avatar_url,gender:$('member-gender').value||null,birthday:$('member-birthday').value||null});$('member-receipt').textContent='Profile saved.';}catch(e){$('error').textContent=e.message;}};
 let adjustment=null;
 $('member-adjust').onsubmit=async event=>{event.preventDefault();const amount=Number($('adjust-amount').value);if(!adjustment&&(!Number.isSafeInteger(amount)||amount===0))return;if(!adjustment&&!confirm(`Change ${num(amount)} Coins for ${p.display_name} (ID ${p.public_id})?`))return;adjustment??={amount,note:$('adjust-note').value,request_id:id()};$('adjust-submit').disabled=true;for(const key of ['adjust-amount','adjust-note'])$(key).disabled=true;try{await api('users/'+encodeURIComponent(uid)+'/adjust','POST',adjustment);adjustment=null;await userDetails(uid);$('member-receipt').textContent='Coins adjusted. Official receipt delivered.';}catch(e){$('error').textContent=e.message;if($('adjust-submit')){$('adjust-submit').disabled=false;$('adjust-submit').textContent='Retry same adjustment';}}};
 if($('member-ban'))$('member-ban').onsubmit=async event=>{event.preventDefault();$('ban-submit').disabled=true;try{await api('users/'+encodeURIComponent(uid)+'/ban','POST',{enabled:!data.banned,reason:$('ban-reason').value});await userDetails(uid);}catch(e){$('error').textContent=e.message;if($('ban-submit'))$('ban-submit').disabled=false;}};
}
async function memberHistory(uid){
 let mode='ledger',rows=[],before=null,more=true;
 $('member-history-panel').innerHTML='<div class="space"><button id="ledger-tab">Coin / Diamond ledger</button><button id="gift-tab">Sent / received gifts</button><div id="member-history-rows"></div><button id="member-history-more">Load older history</button></div>';
 async function load(){
  $('member-history-more').disabled=true;
  try{const result=await api('users/'+encodeURIComponent(uid)+'/history'+(before?'?before='+before:''));const items=result[mode];rows.push(...items);more=result[mode==='ledger'?'has_more':'gift_has_more'];if(items.length)before=items.at(-1)[mode==='ledger'?'cursor':'id'];
   $('member-history-rows').innerHTML=mode==='ledger'?table(['Date','Type','Coins','Diamonds','Reference'],rows.map(r=>`<tr><td>${esc(new Date(r.created_at*1000).toLocaleString())}</td><td>${esc(r.kind)}</td><td>${esc(r.coin_delta)}</td><td>${esc(r.diamond_delta)}</td><td class="details">${esc(r.reference)}</td></tr>`)):table(['Date','Gift','From','To','Coins per recipient','Room'],rows.map(r=>`<tr><td>${esc(new Date(r.created_at*1000).toLocaleString())}</td><td>${esc(r.title)}</td><td>${esc(r.sender_name)}<br><small>${esc(r.sender_uid)}</small></td><td>${esc(r.recipient_name)}<br><small>${esc(r.recipient_uid)}</small></td><td>${r.price===null?'See historical ledger':num(r.price)}</td><td>${esc(r.room_id)}</td></tr>`));
   $('member-history-more').hidden=!more;
  }finally{if($('member-history-more'))$('member-history-more').disabled=false;}
 }
 for(const kind of ['ledger','gift'])$(kind+'-tab').onclick=async()=>{mode=kind==='gift'?'gifts':'ledger';rows=[];before=null;try{await load();}catch(e){$('error').textContent=e.message;}};
 $('member-history-more').onclick=()=>load().catch(e=>{$('error').textContent=e.message;});await load();
}
async function agencies(){
 const rows=(await api('agencies')).items;
 $('panel').innerHTML=`<section class="card"><h2>Agency directory</h2>${table(['Agency','Manager','Members','Action'],rows.map(a=>`<tr><td>${esc(a.name)}</td><td>${esc(a.manager_name)}<br>${esc(a.manager)}</td><td>${num(a.members)}</td><td><button data-agency-roster="${esc(a.id)}">Manage members</button><button data-agency-remove="${esc(a.id)}">Hide agency</button></td></tr>`))}<form id="agency-form"><label>Agency name<input id="agency-name" minlength="2" maxlength="60" required></label><label>Manager public ID or Firebase account ID<input id="agency-manager" maxlength="128" required></label><p>Find the manager in Members and enter their public ID. Agency managers can approve join requests; this grants no global admin or wallet access.</p><button>Create agency</button></form><p id="agency-receipt"></p><div id="agency-members"></div></section>`;
 $('agency-form').onsubmit=async event=>{event.preventDefault();try{await api('agencies','POST',{id:id(),name:$('agency-name').value,manager:$('agency-manager').value.trim(),active:true});await agencies();$('agency-receipt').textContent='Agency created.';}catch(e){$('error').textContent=e.message;}};
 root.querySelectorAll('[data-agency-roster]').forEach(b=>b.onclick=async()=>{try{const roster=(await api('agencies/'+b.dataset.agencyRoster+'/members')).items;$('agency-members').innerHTML=roster.map(p=>`<p>${esc(p.name)} · ${esc(p.status)} <button data-agency-person="${esc(p.uid)}" data-enabled="true">Approve</button> <button data-agency-person="${esc(p.uid)}" data-enabled="false">Remove</button></p>`).join('')||'No join requests or members yet.';root.querySelectorAll('[data-agency-person]').forEach(button=>button.onclick=async()=>{try{await api('agencies/'+b.dataset.agencyRoster+'/members/'+encodeURIComponent(button.dataset.agencyPerson),'PUT',{enabled:button.dataset.enabled==='true'});b.click();}catch(e){$('error').textContent=e.message;}});}catch(e){$('error').textContent=e.message;}});
 root.querySelectorAll('[data-agency-remove]').forEach(b=>b.onclick=async()=>{try{const a=rows.find(x=>x.id===b.dataset.agencyRemove);await api('agencies','POST',{id:a.id,name:a.name,manager:a.manager,active:false});await agencies();}catch(e){$('error').textContent=e.message;}});
}

async function rewards(){
 const data=await api('rewards');const catalog=(await api('catalog')).items.filter(a=>a.active&&!['gift','banner'].includes(a.kind));
 const options=catalog.map(a=>`<option value="${esc(a.id)}">${esc(a.kind)} · ${esc(a.title)}</option>`).join('');
 $('panel').innerHTML=`<section class="card"><h2>Publish reward campaign</h2><p>Only confirmed activity counts. Rich: gift Coins sent; Charm: gift Diamonds received; Game wins: payouts; Recharge: approved recharge receipts. Scores exclude imports, refunds, adjustments and reward credits. Ties sort by permanent server account order. All dates are UTC.</p><form id="reward-form"><label>Title<input id="reward-title" required minlength="3" maxlength="100"></label><label>Campaign<select id="reward-category"><option value="ranking">Ranking rewards</option><option value="event">Event rewards</option><option value="recharge">Recharge milestone reward</option></select></label><label>Metric<select id="reward-metric"><option value="rich">Rich: gift Coins sent</option><option value="charm">Charm: gift Diamonds received</option><option value="play">Game win payouts</option><option value="recharge">Recharge receipts</option></select></label><label>Start (UTC)<input id="reward-start" type="datetime-local" required></label><label>End (UTC)<input id="reward-end" type="datetime-local" required></label><label>Repeat<select id="reward-repeat"><option value="none">No repeat</option><option value="daily">Daily (exact 24-hour UTC window)</option><option value="weekly">Weekly (exact 7-day UTC window)</option><option value="monthly">Calendar month</option></select></label><label><input id="reward-auto" type="checkbox" checked>Automatically credit qualified rewards after verification</label><label>Minimum score / recharge milestone<input id="reward-threshold" type="number" min="1" max="1000000000000" value="1" step="1" required></label><p>Ranking and event rewards are determined after closing. A recharge milestone can be claimed once per member after qualification. Choose up to three wearable items per rank. Leave unused ranks at zero with no items.</p>${Array.from({length:10},(_,i)=>i+1).map(rank=>`<fieldset class="card space"><legend>Top ${rank} / milestone ${rank===1?'(Recharge uses this prize)':''}</legend><label>Reward Coins<input id="reward-coins-${rank}" type="number" min="0" max="1000000000" step="1" value="${(11-rank)*10000}" required></label><label>Collection items (up to 3)<select multiple id="reward-items-${rank}">${options}</select></label><label>Collection duration (days)<input id="reward-days-${rank}" type="number" min="1" max="365" value="7" required></label></fieldset>`).join('')}<p class="help">Publishing promises these rewards. Rules are fixed once published; cancellation is allowed only before the start. Native Coins are issued on claim with an audit record and private official receipt. Permanent collection ownership is preserved.</p><button id="reward-submit">Review & publish rewards</button></form><p id="reward-receipt" role="status"></p></section><section class="card space"><h2>Campaigns</h2>${data.items.map(c=>`<div class="card space"><h3>${esc(c.title)}</h3><p>${esc(c.category)} · ${esc(c.metric)} · ${esc(c.status)} · minimum ${num(c.threshold)}</p><p>${new Date(c.starts_at*1000).toISOString()} → ${new Date(c.ends_at*1000).toISOString()}</p>${c.prizes.map(p=>`<p>Top ${p.rank}: ${num(p.coins)} Coins · ${p.items.map(a=>esc(a.title)).join(', ')||'no collection item'} · ${p.days} days</p>`).join('')}<p>${c.winners.map(w=>`#${w.rank} ${esc(w.name)} (${esc(w.public_id)}) · ${num(w.score)} · ${w.claimed_at?'claimed':'awaiting claim'}`).join('<br>')||'Results appear after closing.'}</p>${c.status==='active'&&c.repeat&&c.repeat!=='none'?`<button data-stop-repeat="${esc(c.id)}">Stop future repeats</button>`:''}${c.status==='active'&&c.starts_at>data.server_now?`<button data-cancel-reward="${esc(c.id)}">Cancel scheduled campaign</button>`:''}</div>`).join('')||'<p>No campaigns yet.</p>'}</section>`;
 let draft=null;
 $('reward-category').onchange=()=>{const recharge=$('reward-category').value==='recharge';if(recharge)$('reward-metric').value='recharge';$('reward-metric').disabled=recharge;};
 $('reward-form').onsubmit=async event=>{event.preventDefault();
  if(!draft){const prizes=Array.from({length:10},(_,i)=>i+1).filter(rank=>$('reward-category').value!=='recharge'||rank===1).map(rank=>({rank,coins:Number($('reward-coins-'+rank).value),item_ids:[...$('reward-items-'+rank).selectedOptions].map(o=>o.value),days:Number($('reward-days-'+rank).value)})).filter(p=>p.coins>0||p.item_ids.length);
   if(!prizes.length){$('error').textContent='Add at least one prize.';return;}
   const dates=[$('reward-start').value,$('reward-end').value].map(s=>Date.parse(s+'Z')/1000);
   if(!dates.every(Number.isSafeInteger)||dates[1]<=dates[0]){$('error').textContent='Choose valid UTC start and end times.';return;}
   if(!confirm('Publish these reward amounts and dates? Published rules cannot be changed.'))return;
   draft={id:id(),title:$('reward-title').value,category:$('reward-category').value,metric:$('reward-metric').value,starts_at:dates[0],ends_at:dates[1],threshold:Number($('reward-threshold').value),repeat:$('reward-repeat').value,auto_claim:$('reward-auto').checked,prizes};
  }
  $('reward-submit').disabled=true;for(const el of $('reward-form').querySelectorAll('input,select'))el.disabled=true;
  try{await api('rewards','POST',draft);draft=null;await rewards();$('reward-receipt').textContent='Reward campaign published.';}catch(e){$('error').textContent=e.message;$('reward-submit').disabled=false;$('reward-submit').textContent='Retry same campaign';}
 };
 root.querySelectorAll('[data-stop-repeat]').forEach(b=>b.onclick=async()=>{try{await api('rewards/'+encodeURIComponent(b.dataset.stopRepeat)+'/stop-repeat','POST');await rewards();}catch(e){$('error').textContent=e.message;}});
 root.querySelectorAll('[data-cancel-reward]').forEach(b=>b.onclick=async()=>{if(!confirm('Cancel this scheduled campaign?'))return;b.disabled=true;try{await api('rewards/'+encodeURIComponent(b.dataset.cancelReward),'DELETE');await rewards();}catch(e){$('error').textContent=e.message;b.disabled=false;}});
}
async function security(){
 const data=await api('security');
 $('panel').innerHTML=`<section class="card"><h2>Authenticator protection</h2><p>2FA: <b>${data.enabled?'Enabled':'Not enabled'}</b>. Recovery codes remaining: ${num(data.recovery_remaining)}.</p><form id="security-factor"><label>Current admin password<input id="security-password" type="password" autocomplete="current-password" required></label>${data.enabled?'<label>Current authenticator or unused recovery code<input id="security-otp" autocomplete="one-time-code" maxlength="32" required></label>':''}<button>${data.enabled?'Disable 2FA':'Set up authenticator'}</button></form><div id="security-enrollment"></div><p class="help">Keep recovery codes privately. A fresh code or unused recovery code is required for each login. Enabling 2FA revokes other active sessions.</p></section><section class="card space"><h2>Your admin sessions</h2>${data.sessions.map(s=>`<article class="card space"><b>${s.current?'This session':'Other session'}</b><p>${esc(s.user_agent||'Device not observed yet')} · ${esc(s.remote_ip||'')}</p><p>Last seen ${s.last_seen?new Date(s.last_seen*1000).toISOString():'not recorded'} · Expires ${new Date(s.expires*1000).toISOString()}</p><button data-revoke-session="${esc(s.id)}">${s.current?'Sign out this session':'Revoke session'}</button></article>`).join('')}</section>`;
 $('security-factor').onsubmit=async e=>{e.preventDefault();const password=$('security-password').value;try{
  if(data.enabled){await api('security/disable','POST',{password,otp:$('security-otp').value.trim()});await security();return;}
  const enrollment=await api('security/enroll','POST',{password});$('security-password').value='';
  $('security-enrollment').innerHTML=`<p>Add this setup key to your authenticator as a time-based account named Sovera.</p><pre class="details">${esc(enrollment.secret)}</pre><form id="security-confirm"><label>Six-digit authenticator code<input id="security-confirm-code" pattern="[0-9]{6}" inputmode="numeric" required></label><button>Confirm & enable 2FA</button></form>`;
  $('security-confirm').onsubmit=async ev=>{ev.preventDefault();try{const result=await api('security/confirm','POST',{otp:$('security-confirm-code').value});$('security-enrollment').innerHTML=`<p><b>2FA enabled. Save these recovery codes now; they are shown once.</b></p><pre>${result.recovery_codes.map(esc).join('\n')}</pre><button id="security-done">I saved the codes</button>`;$('security-done').onclick=security;}catch(err){$('error').textContent=err.message;}};
 }catch(err){$('error').textContent=err.message;}};
 root.querySelectorAll('[data-revoke-session]').forEach(b=>b.onclick=async()=>{try{await api('security/sessions/'+encodeURIComponent(b.dataset.revokeSession),'DELETE');await start();}catch(e){$('error').textContent=e.message;}});
}
async function operations(){
 const d=await api('operations'),health=await api('operations/maintenance');
 $('panel').innerHTML=`<div class="metrics">${[['Active members / 24h',d.active_24h],['Online in rooms',d.online],['Outstanding Coins',d.coins_outstanding],['Outstanding Diamonds',d.diamonds_outstanding]].map(([k,v])=>`<section class="card metric"><small>${k}</small><div class="value">${num(v)}</div></section>`).join('')}</div><section class="card space"><h2>30-day virtual currency activity</h2><div style="display:flex;align-items:end;gap:3px;height:110px" role="img" aria-label="Daily verified recharge activity">${d.daily.map(r=>`<div title="${esc(r.day)}: ${num(r.recharged)} recharge Coins" style="flex:1;min-width:3px;border-radius:5px 5px 0 0;background:var(--accent,#00c9bc);height:${Math.max(2,Number(r.recharged)/Math.max(1,...d.daily.map(x=>Number(x.recharged)))*100)}px"></div>`).join('')}</div><p>${esc(d.currency_note)}</p>${table(['UTC date','Transactions','Recharge','Gifts sent','Stakes','Win payouts'],d.daily.map(r=>`<tr>${[r.day,r.transactions,r.recharged,r.gifts,r.stakes,r.winnings].map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`))}<p>Database ${(d.database_bytes/1048576).toFixed(1)} MB · Disk free ${(d.disk_free/1073741824).toFixed(1)} GB · Load ${d.load_average.map(v=>Number(v).toFixed(2)).join(' / ')}</p></section><section class="card space"><h2>Maintenance & verified backup copies</h2><p>${esc(health.restore_note)}</p>${health.jobs.map(j=>`<p>${esc(j.key)}: ${new Date(j.last_run*1000).toISOString()} · ${esc(j.note)}</p>`).join('')||'<p>No maintenance run recorded yet.</p>'}${health.backups.map(b=>`<p>${esc(b.id)} · ${b.verified?'Integrity checked':'Not verified'} · ${Object.keys(b.files).map(esc).join(', ')}</p>`).join('')||'<p>No scheduled backup recorded yet. Deploy the updater to install the timer.</p>'}</section><section class="card space"><h2>Audit & exports</h2><form id="records"><label>Records<select id="record-kind"><option value="ledger">Wallet ledger</option><option value="audit">Admin audit</option><option value="access">Observed device/network activity</option><option value="members">Members</option></select></label><label>Target Firebase UID / member search<input id="record-target" maxlength="128"></label><label>Before record ID<input id="record-before" type="number" min="0" value="0"></label><button>Load records</button><button type="button" id="record-csv">Download CSV</button></form><p class="help">Ledger and audit: 1,000 rows per page; use the oldest ID for the next page. Observed IP/user-agent activity is not proof of a distinct physical device. Activity is kept for 90 days.</p><div id="record-results"></div></section><section class="card space"><h2>Member filters</h2><form id="member-filter"><label>Name / ID<input id="member-q" maxlength="128"></label><label>Country code<input id="member-country" maxlength="3" placeholder="BD"></label><label>Status<select id="member-status"><option value="">All</option><option value="active">Active</option><option value="banned">Banned</option></select></label><label>Minimum Coins<input id="member-min" type="number" min="0" value="0"></label><label>Offset (100 rows per page)<input id="member-offset" type="number" min="0" value="0" step="100"></label><button>Search members</button><button id="member-export" type="button">Download filtered CSV</button></form><div id="member-filter-results"></div></section><section class="card space"><h2>Staff restrictions</h2><form id="policy"><label>Staff Firebase UID<input id="policy-target" required maxlength="128"></label><label>Expiry (UTC, blank = no expiry)<input id="policy-expiry" type="datetime-local"></label><label>Disable capabilities<select id="policy-denied" multiple>${['users','wallet','catalog','publications','support','rooms','reports','programs'].map(v=>`<option>${v}</option>`).join('')}</select></label><button>Save restrictions & revoke staff sessions</button></form><p class="help">Restrictions only reduce the account's assigned role. Owner access cannot be changed here.</p></section>`;
 const query=()=>`operations/records/${$('record-kind').value}?target=${encodeURIComponent($('record-target').value.trim())}&before=${Number($('record-before').value)||0}`;
 $('records').onsubmit=async e=>{e.preventDefault();try{const rows=(await api(query())).items;$('record-results').innerHTML=rows.length?table(Object.keys(rows[0]),rows.map(r=>`<tr>${Object.values(r).map(v=>`<td class="details">${esc(v)}</td>`).join('')}</tr>`)):'No records.';}catch(err){$('error').textContent=err.message;}};
 $('record-csv').onclick=async()=>{try{const r=await fetch('/sovera/control/'+query()+'&csv_export=true',{credentials:'same-origin',cache:'no-store'});if(!r.ok)throw Error('Export failed');const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download='sovera-'+$('record-kind').value+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){$('error').textContent=e.message;}};
 const memberQuery=()=>`operations/members?q=${encodeURIComponent($('member-q').value.trim())}&country=${encodeURIComponent($('member-country').value.trim().toUpperCase())}&status=${$('member-status').value}&minimum=${Number($('member-min').value)||0}&offset=${Number($('member-offset').value)||0}`;
 $('member-filter').onsubmit=async e=>{e.preventDefault();try{const rows=(await api(memberQuery())).items;$('member-filter-results').innerHTML=rows.length?table(Object.keys(rows[0]),rows.map(r=>`<tr>${Object.values(r).map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`)):'No matching members.';}catch(err){$('error').textContent=err.message;}};
 $('member-export').onclick=async()=>{try{const r=await fetch('/sovera/control/'+memberQuery()+'&csv_export=true',{credentials:'same-origin',cache:'no-store'});if(!r.ok)throw Error('Export failed');const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download='sovera-members.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){$('error').textContent=e.message;}};
 $('policy').onsubmit=async e=>{e.preventDefault();try{const expires_at=$('policy-expiry').value?Date.parse($('policy-expiry').value+'Z')/1000:0;await api('operations/policy/'+encodeURIComponent($('policy-target').value.trim()),'PUT',{expires_at,denied:[...$('policy-denied').selectedOptions].map(o=>o.value)});$('error').textContent='Staff restrictions saved.';}catch(err){$('error').textContent=err.message;}};
}
async function moderationRooms(){
 const rows=(await api('rooms')).items;
 $('panel').innerHTML=`<section class="card"><h2>Central room moderation</h2><p>Closing or banning a room removes it from the directory and blocks entry/voice renewal. The server also attempts to disconnect the live room.</p>${rows.map(r=>`<article class="card space"><h3>${esc(r.name)}</h3><p>${esc(r.id)} · Owner ${esc(r.owner_name)} · ${r.occupants} online · ${r.seats} seats</p><form data-room-moderate="${esc(r.id)}"><label>Status<select name="state">${['open','closed','banned'].map(v=>`<option ${v===r.status?'selected':''}>${v}</option>`).join('')}</select></label><label>Reason<input name="reason" minlength="3" maxlength="300" value="${esc(r.reason)}" required></label><button>Apply moderation</button></form><form data-room-presentation="${esc(r.id)}"><h4>Room appearance & chat</h4><label>Theme<select name="theme">${['mid','gold','ocean','rose','forest','sunset'].map(t=>`<option value="${t}" ${t===r.theme?'selected':''}>${t}</option>`).join('')}</select></label><label><input type="checkbox" name="chat" ${r.chat_enabled?'checked':''}> Text chat enabled</label><label>Minimum Wealth Level for chat photos<input name="level" type="number" min="0" max="10000" value="${Number(r.photo_min_level)||0}" required></label><button>Save room settings</button></form></article>`).join('')||'No rooms.'}</section>`;
 root.querySelectorAll('[data-room-presentation]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{await api('rooms/'+encodeURIComponent(f.dataset.roomPresentation)+'/presentation','PUT',{theme:f.elements.theme.value,chat_enabled:f.elements.chat.checked,photo_min_level:Number(f.elements.level.value)});await moderationRooms();$('error').textContent='Room appearance and chat settings saved.';}catch(err){$('error').textContent=err.message;}});
 root.querySelectorAll('[data-room-moderate]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{const r=await api('rooms/'+encodeURIComponent(f.dataset.roomModerate),'PUT',{status:f.elements.state.value,reason:f.elements.reason.value});await moderationRooms();$('error').textContent=r.voice_disconnect_pending?'Room access blocked; live RTC disconnection is pending.':'Room moderation saved.';}catch(err){$('error').textContent=err.message;}});
}
async function programs(){
 const d=await api('programs'),assets=(await api('catalog')).items.filter(a=>a.active&&!['gift','banner'].includes(a.kind));
 $('panel').innerHTML=`<section class="card"><h2>Memberships & recharge offers</h2><p>VIP/SVIP spend real app Coins and grant a membership badge plus selected timed collection items. Recharge offers use manually verified merchant receipts; there is no automatic payment gateway configured.</p>${d.items.map(p=>`<p><b>${esc(p.title)}</b> · ${esc(p.kind)} · ${num(p.coins)} Coins · ${p.days} days · ${p.active?'published':'hidden'} <button data-toggle-pack="${esc(p.id)}">${p.active?'Hide':'Publish'}</button></p>`).join('')}<form id="pack"><label>Type<select id="pack-kind"><option value="vip">VIP</option><option value="svip">SVIP</option><option value="recharge">Manual recharge offer</option></select></label><label>Title<input id="pack-title" required minlength="2" maxlength="80"></label><label>Coins (membership cost / recharge credit)<input id="pack-coins" type="number" min="1" max="1000000000" required></label><label>Membership days<input id="pack-days" type="number" min="1" max="365" value="30" required></label><label>Membership level<input id="pack-level" type="number" min="1" max="20" value="1" required></label><label>Included collection items (up to 5)<select id="pack-items" multiple>${assets.map(a=>`<option value="${esc(a.id)}">${esc(a.title)}</option>`).join('')}</select></label><label>Currency (recharge offers)<input id="pack-currency" value="USD" pattern="[A-Z]{3}" required></label><label>Price in minor currency units (e.g. cents)<input id="pack-price" type="number" min="1" value="100" required></label><label>Payment method<input id="pack-method" value="Manual verification" maxlength="80" required></label><label>Payment instructions (never enter API secrets)<textarea id="pack-instructions" maxlength="800"></textarea></label><button>Review & publish offer</button></form></section><section class="card space"><h2>Qualified referral policy</h2><p>A referral can link one inviter once, during its signup window. The inviter earns a one-time reward only after the referred account receives the configured verified recharge amount. Existing accounts are not treated as new signups.</p><form id="referral-policy"><label><input id="referral-enabled" type="checkbox" ${d.referral_policy.enabled?'checked':''}>Enable referral rewards</label>${[['target','Verified recharge target','recharge_target'],['reward','Reward Coins','reward_coins'],['limit','Inviter lifetime referral limit','inviter_limit'],['days','Signup window in days','join_days']].map(([id,label,k])=>`<label>${label}<input id="referral-${id}" type="number" min="1" value="${d.referral_policy[k]}" required></label>`).join('')}<button>Save future referral policy</button></form></section>`;
 root.querySelectorAll('[data-toggle-pack]').forEach(b=>b.onclick=async()=>{try{const p=d.items.find(x=>x.id===b.dataset.togglePack);await api('programs/packs','POST',{...p,active:!p.active});await programs();}catch(e){$('error').textContent=e.message;}});
 let draft=null;$('pack').onsubmit=async e=>{e.preventDefault();if(!draft&&!confirm('Publish this offer and its price?'))return;draft??={id:id(),kind:$('pack-kind').value,title:$('pack-title').value,coins:Number($('pack-coins').value),days:Number($('pack-days').value),level:Number($('pack-level').value),item_ids:[...$('pack-items').selectedOptions].map(o=>o.value),currency:$('pack-currency').value,price_minor:Number($('pack-price').value),payment_method:$('pack-method').value,instructions:$('pack-instructions').value,active:true};try{await api('programs/packs','POST',draft);draft=null;await programs();}catch(err){$('error').textContent=err.message;}};
 $('referral-policy').onsubmit=async e=>{e.preventDefault();try{await api('programs/referral','POST',{enabled:$('referral-enabled').checked,recharge_target:Number($('referral-target').value),reward_coins:Number($('referral-reward').value),inviter_limit:Number($('referral-limit').value),join_days:Number($('referral-days').value)});$('error').textContent='Future referral policy saved; existing referrals keep their promised terms.';}catch(err){$('error').textContent=err.message;}};
}
